                        errors: ErrorUtils.getMicroSecondOnyxErrorWithTranslationKey('iou.error.genericDeleteError'),
                    },
                },
            }),
        ),
        {
            onyxMethod: Onyx.METHOD.MERGE,
            key: `${ONYXKEYS.COLLECTION.TRANSACTION}${transactionID}`,
            value: {
                errors: ErrorUtils.getMicroSecondOnyxErrorWithTranslationKey('iou.error.genericDeleteError'),
            },
        },
    ];

    API.write(WRITE_COMMANDS.DELETE_MONEY_REQUEST, params, {
        optimisticData,
        successData,
        failureData,
        onyxData: [
            {
                // If we're deleting the last transaction in an IOU report, the report will be deleted, and we'll be navigated to the Concierge chat
                // However, if we're deleting the last transaction in a non-IOU report, the report will not be deleted, and we'll be navigated to the report screen
                // We need to make sure we're not deleting the report if it's a non-IOU report
                onyxMethod: Onyx.METHOD.MERGE,
                key: `${ONYXKEYS.COLLECTION.REPORT}${iouReportID}`,
                value: {
                    hasOutstandingIOU: false,
                    pendingAction: null,
                    errorFields: null,
                    errors: null,
                },
            },
            ...onyxDataToDelete,
        ],
        optimisticData: [
            ...optimisticData,
            {
                onyxMethod: Onyx.METHOD.MERGE,
                key: `${ONYXKEYS.COLLECTION.REPORT}${iouReportID}`,
                value: {
                    hasOutstandingIOU: false,
                },
            },
        ],
        successData: [
            ...successData,
            {
                onyxMethod: Onyx.METHOD.MERGE,
                key: `${ONYXKEYS.COLLECTION.REPORT}${iouReportID}`,
                value: {
                    hasOutstandingIOU: false,
                },
            },
        ],
        failureData: [
            ...failureData,
            ...onyxDataToRestore,
            {
                onyxMethod: Onyx.METHOD.MERGE,
                key: `${ONYXKEYS.COLLECTION.REPORT}${iouReportID}`,
                value: {
                    hasOutstandingIOU: true,
                },
            },
        ],
    });

    if (shouldNavigate) {
        navigateBackAfterDeleteTransaction(iouReport);
    }
}

